# owner: platform
import unittest

from hourglass.rounding import rounded_labels
from hourglass.models import Span

class RoundedLabelTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        spans = [Span(9 * 60 + 4, 17 * 60 + 11)]
        labels = rounded_labels(spans, 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        spans = [Span(5, 65)]
        labels = rounded_labels(spans, 10)
        self.assertEqual(labels, ["00:10-01:10 (1h 0m)"])

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45, 120):
            with self.assertRaises(ValueError):
                rounded_labels([Span(0, 60)], step)

if __name__ == "__main__":
    unittest.main()
